<?php if(!isset($campaigns,$write)){http_response_code(403);exit;}
$aq=is_string($_GET['archivio_q']??null)?trim($_GET['archivio_q']):'';$ast=is_string($_GET['stato']??null)?$_GET['stato']:'';
$archive=array_values(array_filter($campaigns,fn($r)=>($aq===''||dc_contains($r['Oggetto'],$aq))&&($ast===''||$r['StatoEtichetta']===$ast)));
$pages=max(1,(int)ceil(count($archive)/20));$page=max(1,min($pages,(int)($_GET['archivio_pagina']??1)));$archive=array_slice($archive,($page-1)*20,20);
?>
<section class="email-card"><h2>Mail salvate, elaborate e inviate</h2><form method="get" class="email-row"><input type="hidden" name="tab" value="registro"><label>Cerca oggetto<input name="archivio_q" value="<?=em_h($aq)?>" maxlength="250"></label><label>Stato<select name="stato"><option value="">Tutti</option><?php foreach(['Bozza','Elaborata','Parzialmente inviata','Inviata','Da verificare'] as $st):?><option value="<?=em_h($st)?>" <?=$st===$ast?'selected':''?>><?=em_h($st)?></option><?php endforeach;?></select></label><button>Cerca mail</button></form>
<?php foreach($archive as $m):$prepared=$m['Stato']==='preparato';$c=$prepared?em_config($p,(int)$m['ConfigID']):null;?>
<article class="email-campaign" data-campaign-id="<?=(int)$m['ID']?>"><h3>#<?=(int)$m['ID']?> · <?=em_h($m['Oggetto']!==''?$m['Oggetto']:'(Senza oggetto)')?></h3><p><strong><?=em_h($m['StatoEtichetta'])?></strong> · Destinatari <?=(int)$m['Destinatari']?> · Inviate <?=(int)$m['Inviate']?> · Da verificare <?=(int)$m['Incerte']?></p><a href="/invio_email.php?tab=componi&amp;id=<?=(int)$m['ID']?>">Apri mail</a> · <a href="/invio_email.php?tab=registro&amp;id=<?=(int)$m['ID']?>">Mostra destinatari e conferme</a>
<?php if($write):?><form method="post" class="email-copy-form"><input type="hidden" name="csrf" value="<?=em_h(csrf())?>"><input type="hidden" name="action" value="duplicate"><input type="hidden" name="id" value="<?=(int)$m['ID']?>"><label><input type="checkbox" name="copy_recipients" checked> Copia anche i destinatari ancora presenti nella rubrica, aggiornandoli</label><button>Duplica come nuova bozza</button></form>
<details class="email-delete"><summary>Elimina mail dal gestionale</summary><form method="post"><input type="hidden" name="csrf" value="<?=em_h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$m['ID']?>"><input type="hidden" name="version" value="<?=(int)$m['Versione']?>"><label><input type="checkbox" name="confirm" required> Elimina contenuto, destinatari, registro e link di conferma di questa mail. Le email già spedite non vengono ritirate.</label><button>Elimina definitivamente</button></form></details>
<?php if($prepared&&$c&&em_campaign_sendable($p,(int)$m['ID'],$c)):?><form method="post"><input type="hidden" name="csrf" value="<?=em_h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$m['ID']?>"><input type="hidden" name="action" value="send"><input type="hidden" name="send_nonce" value="<?=em_h(em_send_nonce())?>"><label><input type="checkbox" name="confirm" required> Confermo l’invio del prossimo lotto agli indirizzi di questa mail.</label><button>Invia prossimo lotto</button></form><?php elseif($prepared):?><p>Campagna precedente non utilizzabile per nuovi invii. Duplicala e verifica i destinatari.</p><?php endif;?>
<?php if($prepared):?><form method="post"><input type="hidden" name="csrf" value="<?=em_h(csrf())?>"><input type="hidden" name="id" value="<?=(int)$m['ID']?>"><input type="hidden" name="action" value="status"><button>Verifica esiti senza reinviare</button></form><?php endif;endif;?></article>
<?php endforeach;if(!$archive):?><p>Nessuna mail trovata.</p><?php endif;?>
<nav class="email-row" aria-label="Paginazione archivio mail"><?php if($page>1):?><a href="?<?=em_h(http_build_query(['tab'=>'registro','archivio_q'=>$aq,'stato'=>$ast,'archivio_pagina'=>$page-1]))?>">« Precedente</a><?php endif;?><span>Pagina <?=$page?> di <?=$pages?></span><?php if($page<$pages):?><a href="?<?=em_h(http_build_query(['tab'=>'registro','archivio_q'=>$aq,'stato'=>$ast,'archivio_pagina'=>$page+1]))?>">Successiva »</a><?php endif;?></nav>
</section>
